from lib import *
M=mcq;F=tf;S=short
chapter(4,'evs','exploring-our-neighbourhood','Exploring Our Neighbourhood',
 ('The red postbox','Navya rode the bus home with her grandfather and saw a red postbox on the corner. Dada ji told her how, when he was young, he posted letters to his brother in another city. Navya was surprised: did people not have mobile phones then?'),
 [('From letters to the internet',['A letter dropped in a postbox is taken by the postman to the post office, which sorts it by region and sends it on.','Post offices also send parcels and important documents and offer other services.','Long ago people used drumbeats and carvings on rocks, then messengers and pigeons carried letters, and later the postal service began.','New inventions like the telephone, radio and television made communication easier, and today mobile phones and the internet connect us in seconds.']),
  ('Ways to travel',['Buses, e-rickshaws and school buses help people travel and carry goods.','Transport and communication have both improved with time, so places feel closer and work is faster.']),
  ('Places and people near us',['Our neighbourhood has helpful places like the library, post office, bank and market, and helpful people like postal workers and bankers.','We can find places using landmarks and directions, and we can draw and read a simple map of our route.','At a bank we learn the basics of saving money.'])],
 [], ('Describe how a letter travels and how communication has changed.',['Postbox, postman, post office','Older ways were slower','Mobile and internet are faster'],['Letters arrive instantly']),
 ['The post office sorts and sends letters and parcels.','Communication changed from drums and pigeons to phones and internet.','Maps and landmarks help us find places in our neighbourhood.'],
 [M('1',1,'Where does the postman take the letters from the postbox?','To the post office',[('To the school','Letters go to the post office to be sorted'),('To the bank','A bank does not sort letters')],'The post office sorts letters by region and sends them to their destinations.'),
  F('2',1,'Long ago people used pigeons and messengers to carry letters.',True,'Before the postal service, messengers and pigeons carried letters.'),
  M('3',1,'Which invention lets us connect with anyone in seconds?','The internet',[('The drumbeat','Drumbeats only reached nearby people'),('The postbox','A postbox only holds letters')],'The internet and mobile phones let us communicate in seconds.'),
  M('4',2,'What does a post office do with letters?','Sorts them according to regions',[('Reads them aloud','It does not read letters'),('Throws them away','It sends them on')],'Letters are sorted by region and sent to their destinations.'),
  S('5',2,'What do we call things like a big tree or shop that help us find a place?',['landmark','landmarks'],'Landmarks help us read a map and find directions.'),
  F('6',3,'Transport and communication have made the world feel closer.',True,'Faster travel and messages connect people and places.')])
chapter(4,'evs','growing-up-with-nature','Growing Up with Nature',
 ('The flame of the forest','Reena and Amit visited a village near a forest at harvest time. Trees full of bright orange-red Palash flowers lit up the forest, and the village was about to become fully solar-powered. The children found that the village houses, paints and festivals were all connected to nature.'),
 [('Flowers and trees',['The Palash tree is called the flame of the forest because its orange-red flowers make the forest look reddish-orange from far away.','The same flower can have different local names, for example Palash is called Kesuda in Gujarat.']),
  ('Living with natural things',['The village houses are made with clay, hay, cow dung and other natural materials, and walls are decorated with a dye of rice flour and water.','Grandmother painted on cloth using natural colours from flowers, leaves and powdered coloured stones.','Gond art is painting on walls with natural colours showing trees, animals, birds and people.','To make a natural dye, collect flowers, leaves or roots like beetroot, hibiscus and marigold, boil them in water for half an hour to an hour with a lid, and take help from an elder.']),
  ('Caring for nature',['Solar panels give electricity for fans and bulbs, so the village uses sunlight, which does not run out.','Many plants are used as medicine, but we should use nature wisely and not waste it, so there is enough for tomorrow.'])],
 [], ('Tell how people in the village used things from nature.',['Houses from clay and hay','Natural dyes and Gond art','Solar power'],['Natural things are useless']),
 ['The Palash is the flame of the forest.','Villagers use natural materials for homes and colours.','Sustainable living means using nature wisely.'],
 [M('1',1,'Why is the Palash tree called the flame of the forest?','Its orange-red flowers make the forest look reddish-orange',[('It burns easily','It is called flame because of its colour'),('It grows in fire','Fire is not the reason')],'When Palash blooms the forest looks reddish-orange from a distance.'),
  F('2',1,'The village houses were made using natural materials like clay and hay.',True,'The house was made with clay, hay, cow dung and other natural materials.'),
  M('3',1,'What gives electricity to the solar-powered village?','Sunlight through solar panels',[('Coal fire','Solar means sun'),('Wind chimes','They do not make electricity')],'Solar panels turn sunlight into electricity for fans and bulbs.'),
  M('4',2,'Which art uses natural colours to paint trees, animals and birds on walls?','Gond art',[('Sketching with pens','Gond uses natural colours'),('Computer art','Gond is a traditional wall art')],'Gond artists paint nature on walls with natural colours.'),
  S('5',2,'What is Palash called in Gujarat?',['kesuda'],'The same flower can have different local names.'),
  F('6',3,'We should use natural things wisely so they last.',True,'Sustainable living means using nature carefully so it lasts.')])
chapter(4,'evs','food-for-health','Food for Health',
 ('The food festival','At the school food festival, stalls offered dhokla, dal-baati-churma, ragi laddu, jowar upma and many more dishes. At the stall called Mystery Masala, children tasted something sweet, salty and a little bitter all at once. It was Ugadi Pachadi, a traditional food.'),
 [('Six tastes',['Ugadi Pachadi is made with six tastes: sweet, sour, salty, pungent, bitter and astringent.','Jaggery is sweet, tamarind is sour, salt is salty, green chilli is pungent, neem is bitter and raw mango is astringent.','These six tastes are called shad rasa in Ayurveda, and balanced food with all of them is good for health.']),
  ('Why we eat different foods',['Our body needs a variety of food to stay healthy, energetic and strong.','No single food has all the nutrients, so we need foods that give energy, foods that build the body and foods that protect us from disease.','The banner said Colours on Plate, Wellness in Life: a colourful plate has many kinds of foods.']),
  ('Super foods and traditional foods',['Millets like jowar and bajra are rich in nutrients, and ragi laddu and jowar upma are healthy millet foods.','Grandmothers eat jowar and bajra roti in winter and jau roti in summer, which shows traditional food changes with seasons.','Traditional foods of each place help keep families healthy.'])],
 [], ('Explain why we should eat a variety of foods.',['No single food has all nutrients','Energy, body-building and protective foods','Millets are healthy'],['Only sweets are enough']),
 ['Shad rasa are the six tastes: sweet, sour, salty, pungent, bitter, astringent.','We need a variety of food to stay healthy.','Millets are nutrient-rich traditional foods.'],
 [M('1',1,'Which food at the festival had six tastes?','Ugadi Pachadi',[('Roasted corn','It is mainly one taste'),('Hot dosa','It is not made of six tastes')],'Ugadi Pachadi blends all six tastes.'),
  M('2',1,'Which taste does neem have?','Bitter',[('Sweet','Jaggery is sweet'),('Sour','Tamarind is sour')],'Neem is bitter, jaggery is sweet and tamarind is sour.'),
  F('3',1,'One single food contains all the nutrients our body needs.',False,'No single food has everything, so we need variety.'),
  M('4',2,'What are the six tastes called in Ayurveda?','Shad rasa',[('Ras malai','That is a sweet dish'),('Ayur diet','This is not the name')],'The six tastes are known as shad rasa.'),
  S('5',2,'Name one millet mentioned in the chapter.',['jowar','bajra','ragi','jau'],'Jowar, bajra and ragi are millets rich in nutrients.'),
  F('6',3,'Eating a colourful plate with many foods helps us stay healthy.',True,'A variety of foods gives energy, builds the body and protects from disease.')])
chapter(4,'evs','happy-and-healthy-living','Happy and Healthy Living',
 ('Journey of a grain','A grain of rice or wheat travels a long way from the farm to your plate. Many people, animals and parts of nature help it on the way. When we remember them all, we enjoy our food more.'),
 [('What makes us happy',['We feel happy at different times, like when we eat our favourite food or play games.','Healthy living means eating well, playing, resting and feeling thankful.']),
  ('The journey of the grain',['From the seed to the plate the grain passes through many steps, and farmers, sellers, cattle and family members all help.','Soil, water, sunlight and even earthworms and insects play a part.','We should thank everyone who brings us food and never waste it.','In India festivals like Makar Sankranti, Akshay Tritiya, Raja Utsav, Onam and Lohri thank Mother Nature for food.']),
  ('Mindful eating and rest',['In mindful eating the teacher placed one peanut on each child\'s palm. Children closed their eyes and took time to feel and taste it.','Eating slowly and gratefully helps us enjoy food and avoid waste.','We also need exercise and rest so that our body stays strong.'])],
 [], ('Tell the journey of a grain and say who we should thank.',['Farmers, soil, water, sunlight','Sellers and family','Do not waste food'],['Food just comes from shops']),
 ['Many people and elements help a grain reach our plate.','We should thank everyone and not waste food.','Mindful eating, exercise and rest keep us happy and healthy.'],
 [M('1',1,'Which of these helps a grain grow?','Soil, water and sunlight',[('Stone and wood','They do not help a grain grow'),('Tiger and bat','They are not part of this journey')],'Soil, water and sunlight help the grain, along with farmers.'),
  F('2',1,'We should waste food if we do not like it.',False,'We should respect food and take only what we need.'),
  M('3',1,'Which festival is NOT listed for thanking Mother Nature for food?','Christmas',[('Onam','It is listed'),('Lohri','It is listed')],'The chapter lists Makar Sankranti, Akshay Tritiya, Raja Utsav, Onam and Lohri.'),
  M('4',2,'What did the teacher place on each child\'s palm for mindful eating?','One peanut',[('A banana','It was a peanut'),('A laddu','It was a peanut')],'Children closed their eyes and tasted one peanut slowly.'),
  S('5',2,'Name one person who helps a grain reach our plate.',['farmer','shopkeeper','family member'],'Farmers, sellers and family members help bring food to us.'),
  F('6',3,'Exercise and rest help keep our body strong.',True,'We need movement and rest to stay healthy and happy.')])
